/// ```no_run
/// fn divisible_by_3(i_str: String) -> Result<(), String> {
///     let i = i_str
///         .parse::<i32>()
///         .expect("cannot divide the input by three");
///
///     if i % 3 != 0 {
///         Err("Number is not divisible by 3")?
///     }
